//! Whole document, associated owner and content indexes publish jointly.
use super::*;
#[test]
fn document_template_clone_no_slot_exact_owned_storage_and_joint_refusal_recovery(){
 let mut doc=crate::html::parse("<html><body></body></html>");doc.scripting_enabled=true;let mut forms=Forms::new(&doc);let mut page=Page::new();assert_eq!(page.start(&mut doc,&mut forms,&[]).errors,0);assert_eq!(page.console_eval(&mut doc,&mut forms,"var source=new Document();source.appendChild(source.createElementNS('http://www.w3.org/1999/xhtml','template'));var content=source.documentElement.content,owner=content.ownerDocument,nested=owner.createElementNS('http://www.w3.org/1999/xhtml','template');content.appendChild(nested);nested.content.appendChild(owner.createTextNode('held'));").errors,0);let Value::Host(source)=page.runtime.execute("source",&mut Bridge{doc:&mut doc,forms:&mut forms,state:&mut page.state}).unwrap()else{panic!("source")};page.begin_job();let mut b=Bridge{doc:&mut doc,forms:&mut forms,state:&mut page.state};b.state.node_limit=b.doc.nodes.len();
 let before=(b.state.retained,b.state.inert_documents.backing_bytes(),b.state.inert_documents.entries.len(),b.state.inert_documents.generated.len(),b.state.inert_documents.template_documents.len(),b.state.inert_documents.template_contents.len(),b.doc.nodes.len());let limit=b.state.retained_limit;let copies=b.state.copy_work;
 for storage in [true,false]{if storage{b.state.retained_limit=before.0;}else{b.state.copy_work=0;}assert!(b.clone_inert_document(source,true,true).is_err());assert_eq!((b.state.retained,b.state.inert_documents.backing_bytes(),b.state.inert_documents.entries.len(),b.state.inert_documents.generated.len(),b.state.inert_documents.template_documents.len(),b.state.inert_documents.template_contents.len(),b.doc.nodes.len()),before);b.state.retained_limit=limit;b.state.copy_work=copies;}
 let Value::Host(copy)=b.clone_inert_document(source,true,true).unwrap()else{panic!("copy")};let root=b.inert_children(copy).unwrap()[0];let fragment=*b.state.inert_documents.template_contents.get(&root).unwrap();let associated=b.state.inert_documents.node(fragment).unwrap().owner;assert_ne!(associated,copy);assert_eq!(b.state.inert_documents.template_documents.get(&copy),Some(&associated));assert_eq!(b.state.inert_documents.node(root).unwrap().owner,copy);let nested=b.inert_children(fragment).unwrap()[0];let inner=*b.state.inert_documents.template_contents.get(&nested).unwrap();assert_eq!(b.state.inert_documents.node(inner).unwrap().owner,associated);assert_eq!(b.state.inert_documents.node(nested).unwrap().owner,associated);assert_eq!(b.inert_text_value(b.inert_children(inner).unwrap()[0]).unwrap(),"held");assert_eq!(b.doc.nodes.len(),before.6);
 let payload=b.state.inert_documents.entries[before.2..].iter().map(|entry|match entry{Entry::Node(node)=>node.children.capacity()*size_of::<u32>()+match &node.kind{Kind::Document(record)=>record.url.capacity()+record.base_url_override.as_ref().map_or(0,String::capacity)+record.title.capacity(),Kind::Element(s)=>s.capacity(),Kind::Text(s)=>s.capacity(),Kind::Doctype(d)=>d.capacity(),Kind::ProcessingInstruction{target,data}=>target.capacity()+data.capacity(),_=>0},Entry::Implementation=>0,_=>panic!("no-slot clone stays an entry")}).sum::<usize>();assert_eq!(b.state.inert_documents.generated.len(),before.3);assert_eq!(b.state.retained,before.0+payload+b.state.inert_documents.backing_bytes()-before.1);
}
